 gust:['Rachas','km/h',(g,i,t)=>g.v.wind_gusts_10m[i][t],[[0,'#e9f5f2'],[20,'#a7dccb'],[35,'#f2c14e'],[50,'#ef7d36'],[70,'#d6303a'],[100,'#7a1a5b']]],
 rain:['Lluvia','mm/h',(g,i,t)=>g.v.precipitation[i][t],[[0,'rgba(0,0,0,0)'],[.1,'#bfe3ff'],[.5,'#6fb6f2'],[1.5,'#2f7fd6'],[4,'#2b3fb0'],[8,'#7d2fb0']]],
