 $('#mpLayersBtn').onclick=e=>{e.stopPropagation();layers($('#mpLayers').hidden)};$('#mpLayers').addEventListener('click',e=>{if(e.target.closest('[data-layers-close]'))layers(false)});document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;layers(false);if($('#mpWrap')?.classList.contains('is-full'))full(false)});document.addEventListener('pointerdown',e=>{const p=$('#mpLayers');if(p&&!p.hidden&&!e.target.closest('#mpLayers,#mpLayersBtn,[data-layers-open]'))layers(false)});
