/* ---------- Vista 3D (MapLibre con el relieve de AWS Terrain Tiles) ---------- */
function gl3dStyle(){const esri='https://server.arcgisonline.com/ArcGIS/rest/services/';return{version:8,glyphs:'https://demotiles.maplibre.org/font/{fontstack}/{range}.pbf',sources:{base:{type:'raster',tiles:[MP.baseKey==='topo'?IGN_MTN:MP.baseKey==='pnoa'?IGN_PNOA:esri+'World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,maxzoom:18,attribution:MP.baseKey==='topo'?'© IGN':MP.baseKey==='pnoa'?'© IGN · PNOA':'Imágenes © Esri, Maxar'},dem:{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],encoding:'terrarium',tileSize:256,maxzoom:14,attribution:'Relieve: AWS Terrain Tiles'},trails:{type:'geojson',data:{type:'FeatureCollection',features:[]}},ski:{type:'geojson',data:{type:'FeatureCollection',features:[]}},peaks:{type:'geojson',data:{type:'FeatureCollection',features:[]}}},
 layers:[{id:'bg',type:'background',paint:{'background-color':'#1b2428'}},{id:'base',type:'raster',source:'base'},{id:'shade',type:'hillshade',source:'dem',paint:{'hillshade-exaggeration':.25,'hillshade-shadow-color':'#22303a'}},
 {id:'trails',type:'line',source:'trails',paint:{'line-color':['get','c'],'line-width':['interpolate',['linear'],['zoom'],11,1.2,15,3],'line-opacity':.95}},
 {id:'ski-halo',type:'line',source:'ski',paint:{'line-color':'#0b2a3a','line-width':7,'line-opacity':.45,'line-blur':2}},{id:'ski',type:'line',source:'ski',paint:{'line-color':'#38d6ff','line-width':3.2}},
 {id:'peaks',type:'symbol',source:'peaks',layout:{'text-field':['get','n'],'text-font':['Open Sans Semibold'],'text-size':12,'text-offset':[0,-1.1],'text-anchor':'bottom','text-allow-overlap':false},paint:{'text-color':'#ffffff','text-halo-color':'rgba(0,0,0,.75)','text-halo-width':1.4}},{id:'peak-dots',type:'circle',source:'peaks',paint:{'circle-radius':3.5,'circle-color':'#ff5a1f','circle-stroke-color':'#fff','circle-stroke-width':1.5}}],
 terrain:{source:'dem',exaggeration:1.3},sky:{'sky-color':'#7fb2e5','horizon-color':'#dcebf7','fog-color':'#dcebf7','sky-horizon-blend':.6,'horizon-fog-blend':.7,'fog-ground-blend':.4}}}
async function open3d(){if(!MP.map)return;const btn=$('#mp3dBtn');btn.disabled=true;busy('Cargando el relieve en 3D…');try{const lib=await (typeof loadMapLibre==='function'?loadMapLibre():Promise.reject(Error('Motor 3D no disponible')));const el=document.createElement('div');el.id='mp3d';el.className='mp-3dmap';$('#mpWrap').insertBefore(el,$('#mpMap').nextSibling);const c=MP.map.getCenter();
  MP.gl=new lib.Map({container:el,style:gl3dStyle(),center:[c.lng,c.lat],zoom:Math.max(9,MP.map.getZoom()-1),pitch:62,bearing:-20,maxPitch:80,attributionControl:{compact:true},antialias:true});MP.gl.addControl(new lib.NavigationControl({visualizePitch:true}),'bottom-right');
  const ready=()=>{if(!MP.gl||MP.gl._tmReady)return;MP.gl._tmReady=true;sync3dData();busy('');draw3dWx();setTimeout(()=>{sync3dData();draw3dWx()},2500)};MP.gl.on('load',ready);MP.gl.on('idle',()=>{if(MP.gl?._tmReady&&!MP.gl._tmSynced){MP.gl._tmSynced=true;sync3dData();draw3dWx()}});let tries=0;const poll=setInterval(()=>{const g=MP.gl;if(!g){clearInterval(poll);return}let ok=false;try{ok=!!g.getSource('trails')&&!!g.getLayer('trails')}catch{}if(ok){clearInterval(poll);ready()}else if(++tries===40)busy('')},300);MP.gl.on('error',()=>{});MP.gl.on('click',e=>pointSheet(e.lngLat.lat,e.lngLat.lng));MP.gl.on('moveend',()=>{const z=MP.gl.getCenter();MP.map.setView([z.lat,z.lng],Math.min(18,MP.gl.getZoom()+1),{animate:false})});
  $('#mpWrap').classList.add('is-3d');btn.setAttribute('aria-pressed','true');btn.textContent='2D'}catch(e){busy('');notice('No se pudo abrir la vista 3D: '+e.message)}finally{btn.disabled=false}}
function close3d(){if(!MP.gl)return;const c=MP.gl.getCenter(),z=MP.gl.getZoom();MP.gl.remove();MP.gl=null;$('#mp3d')?.remove();$('#mpWrap').classList.remove('is-3d');const b=$('#mp3dBtn');b.setAttribute('aria-pressed','false');b.textContent='3D';MP.map.setView([c.lat,c.lng],Math.round((z+1)*2)/2,{animate:false});onMove()}
function sync3dData(){const g=MP.gl;if(!g?.getSource||!g._tmReady)return;try{ensure3dLayers(g);try{g.getSource('trails')?.setData({type:'FeatureCollection',features:MP.on.trails?MP.trailGeo:[]})}catch{}const ski=[];if(MP.on.ski)for(const {r} of skiDrawn.values())for(const l of r.lines||[])if(l.length>1)ski.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:l.map(p=>[p[1],p[0]])}});try{g.getSource('ski')?.setData({type:'FeatureCollection',features:ski.filter(f=>f.geometry.coordinates.every(c=>finite(c[0])&&finite(c[1])))})}catch{}
 const pk=[];if(MP.on.peaks){const idx=globalThis.TMPlaces?._cache||[];MP.ov.peaks.eachLayer(m=>{const ll=m.getLatLng(),t=m.options.icon?.options?.html||'';const n=t.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();pk.push({type:'Feature',properties:{n},geometry:{type:'Point',coordinates:[ll.lng,ll.lat]}})})}g.getSource('peaks')?.setData({type:'FeatureCollection',features:pk})}catch{}}
