  const track=t.highway==='track',[sac,col]=SAC[t.sac_scale]||(track?['','#f4efe6']:['','#ff7a3d']),info={name:t.name||(track?'Pista':'Sendero'),sac,surface:t.surface,trail_visibility:t.trail_visibility,ref:t.ref,id:e.id,track};
