function renderTracks(){const el=$('#mpTracks');if(!el)return;el.innerHTML=MP.userTracks.map(t=>`<span class="mp-track"><button type="button" data-trk="${esc(t.id)}">${esc(t.name)}</button><button type="button" data-trk-del="${esc(t.id)}" aria-label="Quitar ${esc(t.name)}">×</button></span>`).join('');el.onclick=e=>{const a=e.target.closest('[data-trk]'),d=e.target.closest('[data-trk-del]');if(a){const t=MP.userTracks.find(x=>x.id===a.dataset.trk);if(t){MP.map?.fitBounds(L.latLngBounds(t.lines[0].map(p=>[p[0],p[1]])),{padding:[40,40]});routeSheet({...t,src:'gpx'})}}if(d){MP.userTracks=MP.userTracks.filter(x=>x.id!==d.dataset.trkDel);try{localStorage.setItem('tm.tracks.v17',JSON.stringify(MP.userTracks))}catch{}const s=skiDrawn.get(d.dataset.trkDel);s?.layers.forEach(l=>MP.ov.ski.removeLayer(l));skiDrawn.delete(d.dataset.trkDel);renderTracks()}}}

/* ---------- Pendiente ≥30° (MDT AWS Terrain Tiles, operador central) ---------- */
function slopeLayer(){const SL=[[30,[246,173,85]],[35,[229,62,62]],[40,[155,44,155]],[45,[45,55,72]]];const Slope=L.GridLayer.extend({createTile(c,done){const cv=document.createElement('canvas');cv.width=cv.height=256;const z=c.z;if(!globalThis.TMSnow?.demTile&&typeof demTile!=='function'){setTimeout(()=>done(null,cv));return cv}(globalThis.TMSnow?.demTile||demTile)(z,c.x,c.y).then(e=>{const g=cv.getContext('2d'),img=g.createImageData(256,256),lat=Math.atan(Math.sinh(Math.PI*(1-2*(c.y+.5)/2**z)))*180/Math.PI,res=40075016.686*Math.cos(lat*Math.PI/180)/(256*2**z);
 for(let y=1;y<255;y++)for(let x=1;x<255;x++){const i=y*256+x,s=Math.atan(Math.hypot((e[i+1]-e[i-1])/(2*res),(e[i+256]-e[i-256])/(2*res)))*180/Math.PI;if(s<30||s>72)continue;let col=SL[0][1];for(const [t,cc] of SL)if(s>=t)col=cc;const o=i*4;img.data[o]=col[0];img.data[o+1]=col[1];img.data[o+2]=col[2];img.data[o+3]=150}g.putImageData(img,0,0);done(null,cv)}).catch(err=>done(err,cv));return cv}});return new Slope({minZoom:11,maxZoom:18,maxNativeZoom:15,minNativeZoom:11,opacity:.8,pane:'overlayPane',attribution:'Pendientes: AWS Terrain Tiles'})}

/* ---------- Picos, refugios y webcams ---------- */
async function drawPeaks(){const m=MP.map,key=m.getZoom()+':'+m.getBounds().pad(.1).toBBoxString().split(',').map(v=>(+v).toFixed(2)).join();if(key===MP.peakKey)return;MP.peakKey=key;MP.ov.peaks.clearLayers();if(m.getZoom()<11)return;const idx=await globalThis.TMPlaces?.loadIndex?.()||[],bb=m.getBounds().pad(.1),z=m.getZoom();let n=0;
 for(const p of idx){if(!['pico','refugio','collado','cabaña','lago'].includes(p.kind))continue;if(p.kind==='collado'&&z<13||p.kind==='lago'&&z<13||p.kind==='cabaña'&&z<13)continue;if(!bb.contains([p.lat,p.lon]))continue;if(++n>(z>=14?160:z>=13?100:60))break;
  const ic=L.divIcon({className:'mp-poi mp-'+p.kind,html:`<i></i><span>${esc(p.name)}${finite(p.ele)?` <small>${fmt(p.ele)}</small>`:''}</span>`,iconSize:[14,14],iconAnchor:[7,7]});L.marker([p.lat,p.lon],{icon:ic,keyboard:false,pane:'peaks'}).on('click',ev=>{L.DomEvent.stopPropagation(ev);pointSheet(p.lat,p.lon,false,p)}).addTo(MP.ov.peaks)}}
async function drawCams(){MP.ov.cams.clearLayers();await globalThis.TMWebcams?.load?.();for(const c of globalThis.TMWebcams?.cams||[]){const st=TMWebcams.state(c);if(st==='down')continue;L.marker([c.lat,c.lon],{icon:L.divIcon({className:'mp-cam'+(st==='live'||st==='stream'?' live':''),html:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="7" width="13" height="10" rx="2"/><path d="m16 11 5-3v8l-5-3"/></svg>',iconSize:[28,28],iconAnchor:[14,14]}),title:c.name}).on('click',ev=>{L.DomEvent.stopPropagation(ev);camSheet(c)}).addTo(MP.ov.cams)}}

/* ---------- Fichas en el mapa ---------- */
function sheet(h){const s=$('#mpSheet');if(!s)return;s.hidden=!h;s.innerHTML=h?`<button type="button" class="mp-x" data-sh="close" aria-label="Cerrar ficha">×</button>${h}`:'';uiState()}
function pin(lat,lon){MP.ov.pin.clearLayers();L.circleMarker([lat,lon],{radius:9,color:'#fff',weight:3,fillColor:'#ff5a1f',fillOpacity:1}).addTo(MP.ov.pin)}
